void agrove::bal(tnode *&t) {
    if (t == nullptr) return;
    if (!doBal) { t->h = calcHeight(t); return; }     // switch off: just measure
    int hl = height(t->left), hr = height(t->right);
    if (hl - hr > 1) {                                  // left heavy (+2)
        if (height(t->left->left) < height(t->left->right))
            rotateLeft(t->left);                        // kink: straighten the child first
        rotateRight(t);
    } else if (hr - hl > 1) {                           // right heavy (-2)
        if (height(t->right->right) < height(t->right->left))
            rotateRight(t->right);                      // kink: straighten the child first
        rotateLeft(t);
    } else {
        t->h = calcHeight(t);                           // fine: just record the height
    }
}

