unsigned int agrove::height(tnode *t) const {
    return t == nullptr ? 0 : t->h;     // empty: 0. real: whatever it recorded
}
unsigned int agrove::calcHeight(tnode *t) const {
    if (t == nullptr) return 0;
    return 1 + max(height(t->left), height(t->right));   // me + my taller child
}

bool agrove::insertHelper(kvpair p, tnode *&t) {
    bool r = grove::insertHelper(p, t);   // the base walks down and hooks the node
    bal(t);                               // then, on the way back up: measure me
    return r;
}
void agrove::bal(tnode *&t) {
    if (t == nullptr) return;
    t->h = calcHeight(t);                 // this lesson: just record the height
