bool Tree::hasRec(tnode *t, int v) {
  if (t == nullptr) return false;
  if (v == t->data) return true;
  if (v < t->data) return hasRec(t->left, v);
  return hasRec(t->right, v);
}

void insert(tnode *&t, int v) {
    if (t == nullptr) {        // base case: found the empty spot
        t = new tnode;         // build the node RIGHT HERE
        t->val = v;
        t->left = nullptr;
        t->right = nullptr;
        return;
    }
    if (v < t->val) insert(t->left, v);    // smaller: left child's problem
    else            insert(t->right, v);   // otherwise: right child's problem
}

