int findMin(tnode *p) {      // board version
    while (p->left) {        // is there a left child? then go there
        p = p->left;
    }
    return p->val;           // no more left: this node is the min
}

bool findMin(tnode *t, int &m) {
    if (t == nullptr) return false;     // empty tree: nothing to find
    if (t->left == nullptr) {           // no left child: I am the min
        m = t->val;
        return true;
    }
    return findMin(t->left, m);         // otherwise the min is somewhere in my left
}

