bool insert(tnode *&t, kvpair p) {
    bool r = false;
    if (t) {
        if (p.key < t->p.key)       r = insert(t->left, p);
        else if (p.key > t->p.key)  r = insert(t->right, p);
        // equal key: neither branch runs — r stays false
    } else {
        t = new tnode;
        t->p = p;
        t->left = t->right = nullptr;
        r = true;
    }
    return r;
}

